/* ================================================================
   ЭФФЕКТЫ — трассеры, взрывы, гранаты, смерть отряда, текст
   ================================================================ */

export const эффекты = [];

export function добавитьТрассер(откуда, куда, цвет) {
    эффекты.push({ тип: 'трассер', откуда: { ...откуда }, куда: { ...куда }, цвет, жизнь: 6, максЖизнь: 6 });
}

export function добавитьВзрыв(x, y, цвет, размер) {
    эффекты.push({ тип: 'взрыв', x, y, цвет, размер: размер || 14, жизнь: 12, максЖизнь: 12 });
}

export function добавитьТекст(x, y, текст, цвет) {
    эффекты.push({ тип: 'текст', x, y, текст, цвет, жизнь: 40, максЖизнь: 40 });
}

export function добавитьГранатуЛетящую(откуда, куда) {
    эффекты.push({
        тип: 'граната_летит',
        откуда: { ...откуда },
        куда: { ...куда },
        прогресс: 0,
        жизнь: 30,
        максЖизнь: 30
    });
}

export function добавитьАнимациюСмерти(x, y, цветКоманды) {
    эффекты.push({
        тип: 'смерть_отряда',
        x, y,
        цвет: цветКоманды,
        жизнь: 60, максЖизнь: 60
    });
    for (let i = 0; i < 8; i++) {
        const угол = Math.random() * Math.PI * 2;
        const скорость = 1 + Math.random() * 2;
        эффекты.push({
            тип: 'осколок',
            x, y,
            vx: Math.cos(угол) * скорость,
            vy: Math.sin(угол) * скорость,
            размер: 2 + Math.random() * 2,
            цвет: Math.random() < 0.5 ? цветКоманды : '#3a2a1a',
            жизнь: 40, максЖизнь: 40
        });
    }
    for (let i = 0; i < 3; i++) {
        эффекты.push({
            тип: 'дым',
            x: x + (Math.random() - 0.5) * 20,
            y: y + (Math.random() - 0.5) * 20,
            радиус: 8 + Math.random() * 8,
            жизнь: 80, максЖизнь: 80,
            цвет: 'rgba(40,40,38,0.5)'
        });
    }
}